function onChange(control, oldValue, newValue, isLoading) {
    if (isLoading || newValue == '') {
        return;
    }

    if (newValue == 'faf220a887a9299050d2eca73cbb3591' || newValue == '5e26b5fc1b6525109fde86acdd4bcb03') { //if the report is LAB 1009
        var bldgs = ["8ec379241ba04d10c6c7a8ecbc4bcb61", "146d5f461b5afc1078230d47dc4bcbef", "9c6d5f461b5afc1078230d47dc4bcbf2", "586d5f461b5afc1078230d47dc4bcbff", "c46d5f461b5afc1078230d47dc4bcbcc", "9c6d9f461b5afc1078230d47dc4bcb08", "cb648be12f679c104cbeb1e72799b64b", "d86d9f461b5afc1078230d47dc4bcb0a", "c86d5f461b5afc1078230d47dc4bcbc3", "046d5f461b5afc1078230d47dc4bcbce", "d46d5f461b5afc1078230d47dc4bcbed", "1c6d5f461b5afc1078230d47dc4bcbfd", "806d5f461b5afc1078230d47dc4bcbd9", "506d5f461b5afc1078230d47dc4bcbf1", "e46d9f461b5afc1078230d47dc4bcb19", "8c6d5f461b5afc1078230d47dc4bcbd1", "886d1f461b5afc1078230d47dc4bcbe8", "d06d9f461b5afc1078230d47dc4bcb12", "986d5f461b5afc1078230d47dc4bcbeb", "5c6d9f461b5afc1078230d47dc4bcb15"];

        var listValuename = [];
        for (i = 0; i < bldgs.length; i++) {

            listValuename.push({
                "building": bldgs[i],
				"headquarters": 'false',
				"number_of_deaths": '0',
				"number_of_other_hazardous_occurrences": '0',
				"total_number_of_employees": '0',
				"number_of_office_employees": '0',
				"total_number_of_hours_worked": '0',
				"comments": ''
            });
        }        

        var val = JSON.stringify(listValuename);
        g_form.setValue('lab_1009', val);
    }
}
